export function parseTransactions(lines) {
  return lines
    .filter(Boolean)
    .map(line => {
      const [id, account, kind, amount] = line.split('|');
      return { id, account, kind, amount };
    });
}

export function normalizeTransaction(transaction) {
  return {
    id: transaction.id,
    account: transaction.account,
    cents: Math.round(Number(transaction.amount) * 100),
  };
}

export function buildBalances(transactions) {
  const balances = new Map();

  for (const transaction of transactions) {
    balances.set(
      transaction.account,
      (balances.get(transaction.account) ?? 0) + transaction.cents,
    );
  }

  return balances;
}

export function formatReport(balances) {
  return [...balances.entries()]
    .map(([account, cents]) => ({ account, balance: cents / 100 }))
    .sort((left, right) => left.account.localeCompare(right.account));
}

import { parseTransactions } from './parser.mjs';
import { normalizeTransaction } from './normalizer.mjs';
import { buildBalances } from './ledger.mjs';
import { formatReport } from './report.mjs';

export function processLedger(lines) {
  const parsed = parseTransactions(lines);
  const normalized = parsed.map(normalizeTransaction);
  const balances = buildBalances(normalized);
  return formatReport(balances);
}

